import{_ as t,o as r,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"科学日报 · 2026-10-22（AI 系统架构）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-10-22-ai.md","filePath":"topics/ai-system-architecture/science-daily-2026-10-22-ai.md"}'),e={name:"topics/ai-system-architecture/science-daily-2026-10-22-ai.md"};function i(g,o,a,l,c,d){return r(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-22-ai-系统架构" tabindex="-1">科学日报 · 2026-10-22（AI 系统架构） <a class="header-anchor" href="#科学日报-·-2026-10-22-ai-系统架构" aria-label="Permalink to &quot;科学日报 · 2026-10-22（AI 系统架构）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-22.md</code> — 第41期 ｜ 🤖 AI 板块（5 篇 arXiv） 落盘说明：文件名带 <code>-ai</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code> 及 10-21、10-22 晨报）。</p></blockquote><hr><h2 id="科学日报-2026-10-22-两层-relu-就够——任何-relu-网络都能被精确模拟" tabindex="-1">科学日报 2026-10-22：两层 ReLU 就够——任何 ReLU 网络都能被精确模拟 <a class="header-anchor" href="#科学日报-2026-10-22-两层-relu-就够——任何-relu-网络都能被精确模拟" aria-label="Permalink to &quot;科学日报 2026-10-22：两层 ReLU 就够——任何 ReLU 网络都能被精确模拟&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-22.md</code> ｜ arXiv: 2610.28587</p></blockquote><ul><li>命题：<strong>任意</strong> ReLU 网络都可以被一个<strong>只有两层隐藏层</strong>的 ReLU 网络<strong>精确模拟</strong>（exact，不是近似）。</li><li>证据：给出<strong>两条彼此独立</strong>的证明 —— ① 基于<strong>同调代数中的「填充（fillings）」</strong>；② 一条<strong>直接组合证明</strong>。</li><li>意义：把「<strong>深度</strong>」的理论必要性压到<strong>常数层数</strong> —— 至少对 ReLU 分段线性函数类，<strong>表达能力更多取决于宽度与权重构造方式，而非层数堆叠</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> / <code>llm-scaling-limits.md</code>）：这是给「<strong>深 vs 宽</strong>」争论补上的一个<strong>上限侧刻度</strong>：存在性证明说明「深度不必需」，但<strong>不说明</strong>&quot;两层就够用&quot;在优化层面可达 —— <strong>可表示 ≠ 可学到</strong>。这一点正是本库反复要区分的两类问题（库内 <code>llm-scaling-limits.md</code>、10-13 晨报「理论可达性 vs 训练可达性」）。<strong>读这类结果要连读两句：它把地板抬高了（表达能力下限），但没有搬迁梯子（优化难度）</strong>。</li></ul><hr><h2 id="科学日报-2026-10-22-token-energy-定律——每次解码耗多少焦耳-由「活跃字节-×-实际解码时间」决定" tabindex="-1">科学日报 2026-10-22：Token-Energy 定律——每次解码耗多少焦耳，由「活跃字节 × 实际解码时间」决定 <a class="header-anchor" href="#科学日报-2026-10-22-token-energy-定律——每次解码耗多少焦耳-由「活跃字节-×-实际解码时间」决定" aria-label="Permalink to &quot;科学日报 2026-10-22：Token-Energy 定律——每次解码耗多少焦耳，由「活跃字节 × 实际解码时间」决定&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-22.md</code> ｜ arXiv: 2610.28576</p></blockquote><ul><li>问题：让大模型部署更省电，必须理解<strong>架构、硬件与推理设置</strong>如何共同决定<strong>每生成一个 token 的能耗</strong>。</li><li>方法：<strong>Token-Energy 定律</strong> —— 一个<strong>紧凑、可解释</strong>的模型，把每输出 token 的 <strong>GPU 板级能耗</strong>关联到<strong>两个核心维度</strong>： <ul><li><strong>活跃字节数（active bytes）</strong>：区分「一次解码迭代内<strong>共享</strong>的稠密权重」与「每个请求<strong>私有</strong>、需反复读写的 <strong>KV 历史</strong>」。</li><li><strong>实际解码时间（realized decode time）</strong>：解码总耗时 ÷ 输出 token 数。</li></ul></li><li>形式：两个「字节坐标」与时间合成<strong>统一的仿射形式</strong>，系数按<strong>模型 × 硬件/运行时配置</strong>标定。</li><li>结果：覆盖 <strong>NVIDIA Hopper 与 Blackwell</strong>（含 Hopper 上<strong>双卡张量并行</strong>）；用<strong>固定系数 + 观测解码时间</strong>，留出条件下的<strong>平均能耗估计与实测偏差 ≤ 3.73%</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> / <code>llm-cache-pricing.md</code>）：这条把本库的「<strong>成本会计</strong>」主线从<strong>钱</strong>扩到<strong>焦耳</strong>——且结论结构与 10-21 记录一致：<strong>批处理摊薄的是「共享权重」那一份，长的历史吃的是「私有 KV」那一份</strong>。所以**「上下文越长越贵」不是线性效应，而是按字节私有化的效应**。对本库的一个实际推论：外脑如果把「上下文」当免费资源，就同时付出了<strong>延迟、钱、电</strong>三份成本；<strong>KV 私有化程度才是可调的那个旋钮</strong>（对照 10-21 的 MemT-1.0 / KronLSTM：它们恰好都在改这一项）。</li></ul><hr><h2 id="科学日报-2026-10-22-proof-carrying-contracts——让-ai-智能体「无法违约」的承诺" tabindex="-1">科学日报 2026-10-22：Proof-Carrying Contracts——让 AI 智能体「无法违约」的承诺 <a class="header-anchor" href="#科学日报-2026-10-22-proof-carrying-contracts——让-ai-智能体「无法违约」的承诺" aria-label="Permalink to &quot;科学日报 2026-10-22：Proof-Carrying Contracts——让 AI 智能体「无法违约」的承诺&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-22.md</code> ｜ arXiv: 2610.28484</p></blockquote><ul><li>问题：智能体越来越多<strong>代人或代其它智能体行动</strong>（购买服务、交换信息、委派工作）。它必须遵守的内容写在<strong>指令 / 策略 / 协议</strong>里，但<strong>光有文字无法让它遵守</strong>：它<strong>可能出错</strong>、<strong>被读到的内容带偏</strong>、或<strong>追求不同利益</strong>。</li><li>需求：要让「<strong>智能体经济</strong>」运转，各方需要<strong>无需检视、也无需信任对方智能体</strong>就能依赖的协议。</li><li>方法：<strong>Proof-Carrying Contracts（PC2）</strong>： <ul><li>执行任何请求的<strong>操作前</strong>，智能体必须提交一份<strong>机器可检验的证明</strong>，证明<strong>在其模型允许的所有情况下</strong>该操作都保持<strong>约定的约束</strong>。</li><li>一个名为 <strong>Airlock</strong> 的执行系统<strong>检查证明</strong>并<strong>控制操作访问</strong>。</li><li>各方只规定<strong>要保住的约束</strong>；智能体<strong>自行提供推理</strong>，且<strong>仍可自由调整策略</strong> → 免去「另设一套权限策略、再证明它允许的每个决定都安全」的负担。</li></ul></li><li>保证：证明约束在执行期间的<strong>每一时刻</strong>成立（<strong>即使面对对抗性智能体</strong>），并<strong>界定</strong>这在何种条件下意味着<strong>现实世界中的安全</strong>（这一步很重要：形式保证 ≠ 物理安全）。</li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>cybersecurity</code>）：本库已有「<strong>攻击面在文字层</strong>」的多次实证（10-20 单一&quot;隐含前提&quot;攻击 ORA 翻转答案、10-12 守卫模型&quot;选项通道攻击&quot;把 fail-open 抬到 93–100%）。PC2 是<strong>罕见的方向性解法</strong>：<strong>不靠&quot;读得懂就不要做坏事&quot;，而靠&quot;做任何事都得先交证明&quot;</strong>。这呼应 10-21 晨报归纳的元模式 —— <strong>「约束应该放在必经之路上，而不是放在文本里」</strong>。同时注意它保留的<strong>安全边界</strong>：证明只覆盖<strong>模型内的所有情况</strong>；模型错了，证明没错但世界不安全 —— 又一次「<strong>机制与数字分账</strong>」。</li></ul><hr><h2 id="科学日报-2026-10-22-「涌现」不该只是感叹——用信息分解给「协同」一个可反驳的判据" tabindex="-1">科学日报 2026-10-22：「涌现」不该只是感叹——用信息分解给「协同」一个可反驳的判据 <a class="header-anchor" href="#科学日报-2026-10-22-「涌现」不该只是感叹——用信息分解给「协同」一个可反驳的判据" aria-label="Permalink to &quot;科学日报 2026-10-22：「涌现」不该只是感叹——用信息分解给「协同」一个可反驳的判据&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-22.md</code> ｜ arXiv: 2610.28479</p></blockquote><ul><li>现象：语言模型出现「<strong>无法追溯到单个组件</strong>」的能力、<strong>多智能体系统胜过任一单体</strong>、或<strong>人机组合在各自单独都失败处成功</strong> —— 研究者常称其为「<strong>协同 / 涌现</strong>」。</li><li>问题：这些通常是<strong>非形式化判断</strong>、缺乏理论框架 → 这些说法<strong>无法比较、甚至无法有意义地辩驳</strong>。</li><li>主张：<strong>信息分解（information decomposition）<strong>可作为</strong>统一的形式框架</strong>，把 AI 系统中的协同评估<strong>操作化</strong>。它区分三类性质不同的信息： <ul><li><strong>唯一信息（unique）</strong>：单个组件独有；</li><li><strong>冗余信息（redundant）</strong>：多组件共享；</li><li><strong>协同信息（synergistic）</strong>：<strong>只有&quot;合起来看&quot;才能获得</strong>。</li></ul></li><li>判据（可反驳）：只有当系统行为<strong>携带关于任务相关结果的协同信息</strong>时，才算<strong>涌现</strong>。</li><li>应用：把这把尺子分别用于<strong>注意力头、自主智能体、人机团队</strong> —— 既理顺跨尺度、跨载体的既有知识，也生成「<strong>孤岛式领域会错过</strong>」的<strong>跨层次猜想</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>intelligence-self-learning</code>）：这条是<strong>度量层面的&quot;侧抑制&quot;</strong> —— 它要做的正是本库晨报反复喊的事：<strong>把&quot;看起来很强&quot;拆成&quot;哪一部分在贡献&quot;</strong>。信息分解的三分法对本库自身立刻可用：<strong>auto_link 里&quot;仅文件名互引&quot;的边 ≈ 冗余信息、&quot;某主题独有词&quot;的边 ≈ 唯一信息、&quot;两主题共享机制/故障形态&quot;的边 ≈ 协同信息</strong> —— 而 10-22 晨报实测那条<strong>唯一存活的真边</strong>（自托管 ↔ AI外脑，共同词「LLM 调用与飞书投递同时失效」）<strong>恰好就是协同信息</strong>。也就是说：<strong>真边不是共现得多的边，而是&quot;只有放在一起才成立&quot;的边</strong>。这条可以直接写成 <code>topics/ai-brain/auto-link-quality-fixes.md</code> 的判据条款。</li></ul><hr><h2 id="科学日报-2026-10-22-通用多模态模型天生会「摸」——gpt-6-astra-在接触丰富操作上超过专用-vla" tabindex="-1">科学日报 2026-10-22：通用多模态模型天生会「摸」——GPT-6-Astra 在接触丰富操作上超过专用 VLA <a class="header-anchor" href="#科学日报-2026-10-22-通用多模态模型天生会「摸」——gpt-6-astra-在接触丰富操作上超过专用-vla" aria-label="Permalink to &quot;科学日报 2026-10-22：通用多模态模型天生会「摸」——GPT-6-Astra 在接触丰富操作上超过专用 VLA&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-22.md</code> ｜ arXiv: 2610.28457</p></blockquote><ul><li>问题：通用多模态模型作为<strong>机器人动作策略</strong>很有前景，但它们<strong>是否真正掌握真实交互背后的物理</strong>、并据此指导行动，仍待探究。</li><li>测试台：<strong>接触丰富操作（contact-rich manipulation）</strong> + <strong>触觉理解</strong>作为该能力的实例 —— 任务要求<strong>解读触觉反馈</strong>、并<strong>在受阻后调整动作</strong>；现有触觉策略靠<strong>专门预训练 + 逐任务优化</strong>，数据与训练成本高昂。</li><li>方法：<strong>GPT-as-Tactile-Policy</strong> —— 把<strong>专家示范</strong>总结成<strong>任务指引 + 触觉参照</strong>，用于<strong>接触评估与动作纠正</strong>；<strong>GPT-6-Astra</strong> 把这些上下文与<strong>多模态观测、交互历史</strong>结合，生成控制指令并靠<strong>接触反馈</strong>调整。</li><li>结果：<strong>无需</strong>额外机器人专门预训练、<strong>无需</strong>逐任务策略微调 → 五个 <strong>UniVTAC</strong> 任务 <strong>93.8% 平均成功率</strong>，整体与 SOTA 相当、<strong>部分任务更高</strong>；<strong>Insert Hole</strong> 上触觉反馈把成功率从 <strong>31% 提到 99%</strong>。执行分析显示它确实在做「<strong>接触引导的试探与纠正</strong>」。</li><li>洞察（对本库 <code>ai-system-architecture</code>）：这是「<strong>通用模型 + 正确上下文 = 免专用训练</strong>」的又一实证（库内 10-21 Halcyon「前置条件未必必需」、10-06 Seed 行为耦合可由文档&quot;种下&quot;）。<strong>最值钱的数字不是 93.8%，而是 Insert Hole 的 31%→99%</strong> —— 它精确指出<strong>在哪个环节上，通用模型缺的只是&quot;触觉这一路输入/参照&quot;</strong>，而不是缺训练。对本库的迁移写法：<strong>遇到&quot;这个能力得专门训练&quot;的说法，先问&quot;是不是缺了一路观测，或者缺了一个参照物&quot;</strong>。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ <code>topics/ai-brain/index.md</code> ｜ 第41期 AI 板块</p></blockquote><p>关键词：两层ReLU、Two ReLU Layers、精确模拟、同调代数填充、组合证明、深度非必需、可表示不等于可学到；Token-Energy定律、活跃字节、active bytes、realized decode time、KV私有化、GPU板级能耗、Hopper、Blackwell、张量并行、能耗估计偏差3.73%、上下文成本三份账；Proof-Carrying Contracts、PC2、Airlock、机器可检验证明、对抗性智能体、约束放必经之路、形式保证不等于物理安全、智能体经济；信息分解、information decomposition、唯一信息、冗余信息、协同信息、涌现的可反驳判据、协同信息才是真边、度量层面的侧抑制；GPT-as-Tactile-Policy、GPT-6-Astra、接触丰富操作、UniVTAC、InsertHole 31%到99%、免专用训练、缺一路观测而非缺训练</p><p>关联：<code>topics/ai-system-architecture/science-daily-2026-10-21-ai.md</code>（Halcyon / OpenVLHarness / 物理 RSI / KronLSTM / MemT-1.0）、<code>topics/ai-system-architecture/science-daily-2026-10-20.md</code>、<code>topics/ai-system-architecture/llm-cache-pricing.md</code>、<code>topics/ai-system-architecture/llm-scaling-limits.md</code>、<code>topics/ai-system-architecture/echo-gap-memory-reward-inflation.md</code>、<code>topics/ai-brain/auto-link-quality-fixes.md</code>、<code>topics/ai-brain/knowledge-system-arsenal.md</code></p>',26)])])}const q=t(e,[["render",i]]);export{m as __pageData,q as default};
